import{_ as o,c as e,o as s,ag as r}from"./chunks/framework.Cycwnjj0.js";const a="/assets/custom-prducts-from-azonpress-dashboard.DtU-T_mS.webp",n="/assets/adding-single-custom-product.JCtomCzk.webp",d="/assets/copy-amazon-product-url.BaVk0Gk9.webp",i="/assets/open-the-editor-of-desired-product.BAgGG-6s.webp",u="/assets/edit-option-of-single-custom-product.Bf5ejOKC.webp",c="/assets/edit-product-popup-page.DPHOplrh.webp",p="/assets/preview-of-edited-single-custom-product.Byg4VD47.webp",l="/assets/save-template-or-update-_-save-template-button.CTTnIwee.webp",_=JSON.parse('{"title":"How to Add a Single Custom Product","description":"","frontmatter":{},"headers":[],"relativePath":"guide/custom-product/how-to-add-a-single-custom-product.md","filePath":"guide/custom-product/how-to-add-a-single-custom-product.md"}'),g={name:"guide/custom-product/how-to-add-a-single-custom-product.md"};function h(m,t,w,f,y,b){return s(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="how-to-add-a-single-custom-product" tabindex="-1">How to Add a Single Custom Product <a class="header-anchor" href="#how-to-add-a-single-custom-product" aria-label="Permalink to &quot;How to Add a Single Custom Product&quot;">​</a></h1><p>AzonPress allows you to add custom products to your site where you can fetch the details of the product just by giving the product URL or you can add the product manually. With this feature, besides Amazon, you can also fetch data from other E-Commerce websites such as eBay and Etsy. This article guides you through <strong>Adding a Single Custom Product</strong> with AzonPress.</p><h2 id="add-a-single-custom-product" tabindex="-1">Add A Single Custom Product <a class="header-anchor" href="#add-a-single-custom-product" aria-label="Permalink to &quot;Add A Single Custom Product&quot;">​</a></h2><p>To learn how to add a single custom product, follow the steps with the screenshots below –</p><p>First, go to <strong>Custom Products</strong> from the <strong>WordPress Sidebar</strong> or <strong>AzonPress Navbar</strong>. Now, click the <strong>Add Custom Product</strong> button and a popup page will appear.</p><p><img src="'+a+'" alt="Custom Products from AzonPress Dashboard"></p><p>Now, select the <strong>Single Product Template</strong> option, enter the <strong>Link</strong> of the <strong>Amazon product</strong> that you want to add under the <strong>URL</strong> field, and press the <strong>Continue</strong> button. Your single custom product will be added!</p><p><img src="'+n+'" alt="Adding Single Custom Product"></p><h3 id="get-the-amazon-product-link" tabindex="-1">Get the Amazon Product Link <a class="header-anchor" href="#get-the-amazon-product-link" aria-label="Permalink to &quot;Get the Amazon Product Link&quot;">​</a></h3><p>To learn how to get the URL link of a single Amazon product to fetch the product data into the website, follow the steps in the screenshot below –</p><p>First, go to your <strong>Amazon Associate account</strong>, <strong>search</strong> for the <strong>product</strong> you want to add, and copy the <strong>URL link</strong> from the address bar.</p><p><img src="'+d+'" alt="Copy Amazon Product URL"></p><h2 id="edit-single-custom-product" tabindex="-1">Edit Single Custom Product <a class="header-anchor" href="#edit-single-custom-product" aria-label="Permalink to &quot;Edit Single Custom Product&quot;">​</a></h2><p>The <strong>Edit</strong> option will allow you to modify every detail of the product e.g., Product Info, Product metadata, Image, and Button. Also, you can add a Text and Color option for your Product.</p><p>To learn the details of the editor, follow the steps with screenshots below –</p><p>First, open your desired single custom product by clicking the <strong>Pencil Icon</strong>. You can also <strong>delete</strong> the product by clicking the <strong>Trash</strong> icon if needed.</p><p><img src="'+i+'" alt="Open the editor of desired product"></p><p>Now, click the <strong>Edit</strong> button and a popup page will appear where you will get all the options to edit your product.</p><p><img src="'+u+'" alt="Edit option of single custom product"></p><p>Now, using the options below you can edit your custom products according to your needs.</p><p>Once you complete your edit click the <strong>Update</strong> button to save the changes and if not needed then simply press the <strong>Close</strong> button.</p><p><img src="'+c+'" alt="Edit Product Popup page"></p><p>Here, you can see the Preview of the <strong>Edited</strong> custom product.</p><p><img src="'+p+'" alt="Preview of Edited single custom product"></p><h2 id="customize-template-of-single-products-with-settings" tabindex="-1">Customize Template of Single Products with Settings <a class="header-anchor" href="#customize-template-of-single-products-with-settings" aria-label="Permalink to &quot;Customize Template of Single Products with Settings&quot;">​</a></h2><p>To learn how you can customize the template of your single custom product by using all the available <strong>Settings</strong> options shown in the screenshot below, read this <a href="/guide/custom-product/settings-for-custom-products-template-customization.html">Documentation</a>.</p><p>Once you are done, click the <strong>Save Template</strong> or <strong>Update &amp; Save Template</strong> to ensure all your edits, customization, and changes appear on your site.</p><p><img src="'+l+'" alt="Save Template or Update &amp; Save Template button"></p><p>This is how you can add and edit/customize your Single Custom Product!</p><p>If you have any further questions, concerns, or suggestions, please do not hesitate to contact our support team. Thank you.</p><hr>',31)])])}const A=o(g,[["render",h]]);export{_ as __pageData,A as default};
